            //
            aIngress = (RotL64(aEarthLaneA[((aIndex + 3232U)) & S_BLOCK1], 13U) ^ RotL64(aEarthLaneB[((aIndex + 2405U)) & S_BLOCK1], 41U));
            aIngress ^= RotL64(aKeyRowReadA[((aIndex + 2833U)) & W_KEY1], 30U);
