            aCross ^= RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 4927U)) & S_BLOCK1], 40U);
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCross, 53U) ^ RotL64(aIngress, 5U)) + (RotL64(aCarry, 39U) + RotL64(aPrevious, 24U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterK = (aWandererE + RotL64(aIngress, 19U)) + 0x0E44C37AC34CC345ULL;
            aOrbiterB = ((aWandererG + RotL64(aPrevious, 35U)) + RotL64(aCarry, 51U)) + 0x48D6FB4CA0349482ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aScatter, 57U)) + 0xDC31F5943353A641ULL) + aTwistOrbiterAssignSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterH = ((aWandererI + RotL64(aCross, 29U)) + RotL64(aCarry, 13U)) + 0xA3A8DD315F670E58ULL;
            aOrbiterG = ((aWandererH + RotL64(aIngress, 43U)) + 0x06410412C48D85FAULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterE = (aWandererK + RotL64(aPrevious, 11U)) + 0x7D5E29F186A41A70ULL;
            aOrbiterA = ((aWandererD + RotL64(aScatter, 50U)) + RotL64(aCarry, 27U)) + 0x8D75C43574CEC7BFULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xF45A15BA33B75EDEULL;
