            //
            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x1447670ABF78D4ABULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0x598C91EF0D6856A8ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 29U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xDB1593D235DB3AADULL), 53U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xE152E06D712C0EC1ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x1F62D13ABD4AF653ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x112957B2EDE8950DULL), 41U);
            //
            aIngress = RotL64(aOrbiterG, 29U) ^ aOrbiterK;
