            //
            aWandererD = aWandererD + ((RotL64(aIngress, 28U) + RotL64(aOrbiterG, 35U)) + aOrbiterH);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 43U) + aOrbiterB) + RotL64(aOrbiterK, 23U));
            aWandererG = aWandererG + (((RotL64(aPrevious, 19U) + RotL64(aOrbiterJ, 57U)) + aOrbiterA) + RotL64(aCarry, 57U));
            aWandererE = aWandererE ^ (((RotL64(aCross, 5U) + aOrbiterH) + RotL64(aOrbiterE, 5U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 5U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aPrevious, 37U) + aOrbiterA) + RotL64(aOrbiterE, 47U));
            aWandererK = aWandererK ^ (((RotL64(aScatter, 13U) + aOrbiterB) + RotL64(aOrbiterG, 29U)) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aIngress, 57U) + aOrbiterJ) + RotL64(aOrbiterG, 14U)) + RotL64(aCarry, 5U));
