            aCross = (RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 8902U)) & S_BLOCK1], 44U) ^ RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 8881U)) & S_BLOCK1], 53U));
