            //
            aOrbiterC = (aWandererH + RotL64(aPrevious, 10U)) + 0x1AEB18E0BBE2E6D7ULL;
            aOrbiterD = ((aWandererC + RotL64(aScatter, 21U)) + RotL64(aCarry, 23U)) + 0xD1255171FBC0D2F6ULL;
            aOrbiterE = ((aWandererF + RotL64(aIngress, 29U)) + RotL64(aCarry, 43U)) + 0xCD59DA2D0CE1F58BULL;
            aOrbiterI = (((aWandererE + RotL64(aCross, 37U)) + RotL64(aCarry, 11U)) + 0x6779E2B250FEB648ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterF = ((aWandererK + RotL64(aPrevious, 53U)) + 0xFA0DC4327DEA5276ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterA = (aWandererI + RotL64(aCross, 47U)) + 0xAED2F17068B7779AULL;
            aOrbiterB = (aWandererA + RotL64(aScatter, 3U)) + 0xCD783B04FB3F23ADULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xE8C0C91F5887E341ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x2AD449D1EE85D3B1ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x2B1E673A2D663EB9ULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x6D389F26139433F1ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x1431A50C628B3D05ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1EB3B118B4C104F7ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x33CC9C7C27F2B041ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterA) ^ 0xE25E9BB5BA14354CULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x5561AE0526462725ULL), 27U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0x6937243FB397D51AULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xDC1E57C1083D6ED7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x5C74F34BC57BF159ULL), 21U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0x77D5496A0A2E02A7ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x6029F11765707A3EULL;
            aOrbiterB = RotL64((aOrbiterB * 0x187AC5DD7EBBD5DDULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0xCDEBA56CA7F07988ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xB7B82FA20B49A036ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB890C6F0D975A41BULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x0D6894C65D038A7EULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0x71DB85792E9AE8C2ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x8EFCB203BA3E870BULL), 47U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterC, 19U);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterI, 53U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterB, 47U));
            aIngress = aIngress + RotL64(aOrbiterE, 37U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA + (((RotL64(aScatter, 13U) + aOrbiterB) + RotL64(aOrbiterI, 4U)) + RotL64(aCarry, 5U));
            aWandererE = aWandererE ^ (((RotL64(aIngress, 60U) + aOrbiterE) + RotL64(aOrbiterC, 11U)) + aTwistWandererUpdateSaltF[((aIndex + 27U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aPrevious, 27U) + RotL64(aOrbiterD, 29U)) + aOrbiterB);
            aWandererC = aWandererC ^ (((RotL64(aCross, 37U) + RotL64(aOrbiterE, 57U)) + aOrbiterF) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aScatter, 21U) + RotL64(aOrbiterB, 23U)) + aOrbiterA);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 43U) + aOrbiterB) + RotL64(aOrbiterF, 47U));
