            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x8C9E7D1A20C4D6EEULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xBC60683F7D941296ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x067B55494E199A13ULL), 29U);
