            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x8EA4EC631569220FULL) + aTwistOrbiterUpdateSaltE[((aIndex + 26U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0xEA8CBF405F92F228ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 8U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xD97E525913E9C9ADULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x7A369969DAABEC49ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xE968E14FE1D2CEF5ULL;
