            aIngress = (RotL64(aPoisonLaneA[((aIndex + 932U)) & S_BLOCK1], 4U) ^ RotL64(aPoisonLaneB[((aIndex + 5986U)) & S_BLOCK1], 47U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 4936U)) & W_KEY1], 37U) ^ RotL64(aWaterLaneD[((aIndex + 2090U)) & S_BLOCK1], 29U));
