            aCross = (RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 5657U)) & S_BLOCK1], 21U) ^ RotL64(aSoilLaneA[((S_BLOCK1 - aIndex + 2320U)) & S_BLOCK1], 53U));
            aCross ^= (RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 1702U)) & S_BLOCK1], 11U) ^ RotL64(aEarthLaneD[((aIndex + 7665U)) & S_BLOCK1], 34U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 58U) ^ RotL64(aCarry, 43U)) ^ (RotL64(aPrevious, 11U) + RotL64(aCross, 27U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterA = (((aWandererI + RotL64(aIngress, 19U)) + RotL64(aCarry, 47U)) + 0xA12E877C1A095EE2ULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 8U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aPrevious, 47U)) + RotL64(aCarry, 11U)) + 0xF501B4D1D9CFB069ULL;
            aOrbiterE = (aWandererF + RotL64(aCross, 27U)) + 0x246378FD4DAA2341ULL;
            aOrbiterB = (aWandererH + RotL64(aScatter, 5U)) + 0x1F5C8BF3D5E3BB0DULL;
            aOrbiterH = ((aWandererK + RotL64(aCross, 13U)) + RotL64(aCarry, 27U)) + 0x1BAD6F3AAF60F3A1ULL;
            aOrbiterG = (aWandererB + RotL64(aIngress, 41U)) + 0xD5AA3A91DF889964ULL;
            aOrbiterF = ((aWandererG + RotL64(aScatter, 58U)) + 0xBF9B0299DCC6CAD1ULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 22U)) & S_SALT1];
            //
            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0x944413A86A98360DULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x6CB4AFBBAE66CA63ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x30CECA5BA71CE1D9ULL), 21U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x371B442CB388C1BCULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0xD87B8675D126A1C6ULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xBB81C18BD269A08DULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x9C8AE6BB7E0F61FDULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xADE5E2AEC35CB110ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x53063512028FE68DULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0xB0A98341F3B4C405ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x6C1529A8EED571F2ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3F5AFCFBADDD0CCBULL), 5U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x942B6AED57899211ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x964D8DEE8A49FDD7ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x329E9F7962602455ULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xFB75196688E6D7D8ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x8BDD0D575DB339D8ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 26U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x183398A7DC61048BULL), 51U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterE) + 0x34AEB947E080B93DULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0xE9F18AFE0737DC74ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x05837C7349C4CA27ULL), 39U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterE, 11U);
            aIngress = aIngress + (RotL64(aOrbiterG, 35U) ^ aOrbiterH);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterB, 3U));
            aIngress = aIngress + RotL64(aOrbiterA, 19U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 41U) + aOrbiterH) + RotL64(aOrbiterF, 29U));
