            aWandererB = aWandererB ^ ((RotL64(aPrevious, 23U) + RotL64(aOrbiterF, 47U)) + aOrbiterG);
            aWandererH = aWandererH + ((((RotL64(aScatter, 13U) + aOrbiterC) + RotL64(aOrbiterB, 3U)) + RotL64(aCarry, 11U)) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 7U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aIngress, 53U) + RotL64(aOrbiterG, 37U)) + aOrbiterH);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererH, 21U));
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererF, 35U));
            aCarry = aCarry + (RotL64(aWandererI, 47U) ^ aWandererG);
            aCarry = aCarry + RotL64(aWandererB, 60U);
            aCarry = aCarry + RotL64(aIngress, 41U);
            aCarry = TwistMix64::DiffuseC(aCarry);
            //
            aShadowLaneA[aIndex] = aIngress;
