        for (std::size_t aIndex = 0U; aIndex < static_cast<std::size_t>(S_BLOCK); aIndex += 1U) {
            //
            aPrevious = aIngress;
            //
            aIngress = (RotL64(aShadowLaneA[((aIndex + 10917U)) & S_BLOCK1], 51U) ^ RotL64(aPoisonLaneC[((aIndex + 10365U)) & S_BLOCK1], 43U));
            aIngress ^= (RotL64(aSoilLaneB[((aIndex + 9006U)) & S_BLOCK1], 27U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 14354U)) & S_BLOCK1], 6U));
            aIngress = TwistMix64::DiffuseB(aIngress);
            //
            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 9072U)) & S_BLOCK1], 23U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 14024U)) & S_BLOCK1], 12U));
            aCross ^= (RotL64(aLightningLaneA[((S_BLOCK1 - aIndex + 8445U)) & S_BLOCK1], 35U) ^ RotL64(aSoilLaneC[((aIndex + 11458U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 5U) + RotL64(aCross, 35U)) ^ (RotL64(aCarry, 50U) ^ RotL64(aPrevious, 21U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterG = ((aWandererJ + RotL64(aIngress, 27U)) + RotL64(aCarry, 13U)) + 0xBF3C8AA1278622F4ULL;
            aOrbiterF = (aWandererC + RotL64(aCross, 21U)) + 0x84AAF444B3F6F05BULL;
            aOrbiterA = (aWandererG + RotL64(aScatter, 47U)) + 0xC2899A4989658092ULL;
            aOrbiterJ = ((aWandererF + RotL64(aPrevious, 53U)) + RotL64(aCarry, 53U)) + 0xC652302736F4AA1FULL;
            aOrbiterE = ((aWandererH + RotL64(aIngress, 5U)) + 0x2CC5D3EA886F4C3FULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterI = (aWandererK + RotL64(aPrevious, 13U)) + 0x44825AE70F919433ULL;
            aOrbiterD = (((aWandererB + RotL64(aCross, 38U)) + RotL64(aCarry, 27U)) + 0x2C0C2FA2AE1D9179ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x86A4E217AA2AEC11ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x06D354B3D6E5B0CFULL;
            aOrbiterA = RotL64((aOrbiterA * 0x1037EC07CFBD6053ULL), 51U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x43B24A6F102EA76EULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x046704B0EF7DFBDEULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xC557E8A7C24D252DULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x74E36150874AE4FAULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x088B68B09B72D562ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x2194FC7106A84F4FULL), 57U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x310875B6621D3C83ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xC70425832CB21151ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1AD987D9AE48372BULL), 11U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0xD9E91CEC0E85EB1BULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x13A51ACC40E20312ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x37C61E276B0DEA2DULL), 41U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x3B74EC67D0F773DFULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0xAC631183D7BAD62FULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8A4936A2D62E6CAFULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x1AD6EF65B1E8DE50ULL) + aKeyRotateOrbiterUpdateSaltC[((aIndex + 7U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterA) ^ 0xCB93ADB5A1EEC4E1ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 21U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x4ABB8EBF54976E77ULL), 19U);
            //
            aIngress = aOrbiterE ^ RotL64(aOrbiterG, 57U);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterF, 35U));
            aIngress = aIngress + (RotL64(aOrbiterJ, 47U) ^ aOrbiterD);
            aIngress = aIngress + RotL64(aOrbiterA, 13U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererH = aWandererH + (((RotL64(aIngress, 35U) + RotL64(aOrbiterE, 46U)) + aOrbiterF) + RotL64(aCarry, 13U));
            aWandererJ = aWandererJ ^ (((RotL64(aCross, 19U) + RotL64(aOrbiterE, 5U)) + aOrbiterD) + aKeyRotateWandererUpdateSaltC[(((31U - aIndex) + 26U)) & S_SALT1]);
            aWandererF = aWandererF + ((((RotL64(aPrevious, 29U) + aOrbiterI) + RotL64(aOrbiterA, 21U)) + RotL64(aCarry, 35U)) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aScatter, 47U) + aOrbiterG) + RotL64(aOrbiterF, 35U));
            aWandererB = aWandererB + ((RotL64(aIngress, 6U) + aOrbiterJ) + RotL64(aOrbiterA, 13U));
            aWandererC = aWandererC ^ ((RotL64(aPrevious, 41U) + aOrbiterG) + RotL64(aOrbiterE, 57U));
            aWandererK = aWandererK + ((RotL64(aScatter, 57U) + aOrbiterD) + RotL64(aOrbiterJ, 27U));
            //
            aCarry = aCarry + (aWandererG ^ RotL64(aWandererF, 41U));
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererH, 47U));
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererK, 24U));
            aCarry = aCarry + RotL64(aWandererB, 37U);
            aCarry = aCarry + RotL64(aIngress, 57U);
            aCarry = TwistMix64::DiffuseC(aCarry);
            //
            aShadowLaneB[S_BLOCK1 - aIndex] = aIngress;
        }
    
        //
        // grow_a_loop_a loop 3
        //
        // Ingress:
        //      aShadowLaneB (-->), aPoisonLaneD (-->), aPlasmaLaneD (-->), aHeartLaneC (<-?->)
        //
        // Cross:
        //      aShadowLaneA (<--), aPoisonLaneB (<--), aLightningLaneC (<--), aMagmaLaneC (<-?->)
        //
        // Destination:
        //      aShadowLaneC
