            aOrbiterD = ((aWandererA + RotL64(aIngress, 35U)) + RotL64(aCarry, 51U)) + 0xEE798AD19D835113ULL;
            aOrbiterG = ((aWandererJ + RotL64(aPrevious, 47U)) + 0x24378810B19E22D9ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 25U)) & S_SALT1];
