            aOrbiterC = ((aWandererD + RotL64(aPrevious, 3U)) + 0x3F4BF69522FE8866ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterJ = (aWandererC + RotL64(aIngress, 23U)) + 0x1F68A8C930536114ULL;
