            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x60B7A32582851CE3ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x5738670EED48F37CULL;
            aOrbiterC = RotL64((aOrbiterC * 0xB995F9D75442E683ULL), 11U);
