            aCross = (RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 7303U)) & S_BLOCK1], 27U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 2134U)) & S_BLOCK1], 39U));
            aCross ^= (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 5054U)) & S_BLOCK1], 4U) ^ RotL64(aPlasmaLaneD[((S_BLOCK1 - aIndex + 2089U)) & S_BLOCK1], 13U));
