            aWandererG = aWandererG ^ (((RotL64(aIngress, 20U) + RotL64(aOrbiterJ, 23U)) + aOrbiterB) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aCross, 11U) + aOrbiterD) + RotL64(aOrbiterE, 29U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 29U) + aOrbiterJ) + RotL64(aOrbiterA, 58U));
