            aWandererH = aWandererH ^ ((RotL64(aScatter, 47U) + aOrbiterB) + RotL64(aOrbiterK, 5U));
            aWandererJ = aWandererJ + ((RotL64(aCross, 35U) + RotL64(aOrbiterI, 11U)) + aOrbiterG);
            aWandererI = aWandererI ^ ((RotL64(aIngress, 39U) + RotL64(aOrbiterF, 42U)) + aOrbiterG);
            aWandererK = aWandererK + ((((RotL64(aCross, 58U) + aOrbiterK) + RotL64(aOrbiterF, 47U)) + RotL64(aCarry, 3U)) + aKeyRotateWandererUpdateSaltA[((aIndex + 13U)) & S_SALT1]);
