            aOrbiterF = ((aWandererI + RotL64(aPrevious, 47U)) + 0x193172B289781B48ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 16U)) & S_SALT1];
            aOrbiterK = ((aWandererE + RotL64(aScatter, 5U)) + 0x5AE50442837C40CEULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 23U)) & S_SALT1];
