            aOrbiterD = ((aWandererB + RotL64(aCross, 43U)) + RotL64(aCarry, 39U)) + 0x2F48F46F6CAAD7CAULL;
            aOrbiterI = ((aWandererJ + RotL64(aIngress, 23U)) + RotL64(aCarry, 29U)) + 0x4E9F8E3E49D6C6E7ULL;
            aOrbiterJ = ((aWandererK + RotL64(aScatter, 37U)) + RotL64(aCarry, 13U)) + 0xF0353DEFA385E225ULL;
            aOrbiterE = (aWandererG + RotL64(aPrevious, 27U)) + 0xDCBE99B0DD812338ULL;
            aOrbiterG = (aWandererD + RotL64(aCross, 56U)) + 0x66274BA2A7252E2BULL;
            aOrbiterH = (aWandererH + RotL64(aScatter, 13U)) + 0xE2B0FBD915DC73F4ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x726ED55439F13BE5ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 20U)) & S_SALT1];
