            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterE) + 0x55EDCAB794FAF6A0ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 24U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xFE7C880956CC79CAULL;
            aOrbiterF = RotL64((aOrbiterF * 0x4DB4D48E0AE136C1ULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x7626BD3D27EDC498ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x352919B4D2C21BE1ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x48EE442E5DEF6EBDULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xFE890D0F455441A6ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xB66DE784BDDF68C0ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xE59A8ABA2883066FULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x5D32E52160673D26ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x2D81B8FB29D41888ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x14E56ADC1CBD188DULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x60FEC9220D90CEA7ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x3EB133B64DD55426ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x5F52CC94B8AE4191ULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xF9FBDF124D062CCDULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0xDC96669C6C68AFB3ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xC1032AF413B69583ULL), 23U);
