            aOrbiterH = ((aWandererK + RotL64(aPrevious, 23U)) + RotL64(aCarry, 51U)) + 0x301561B5FD9BE237ULL;
            aOrbiterG = ((aWandererC + RotL64(aScatter, 29U)) + 0x2CFE2C37E9C8C2C2ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 17U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x53E85FB55C603D13ULL;
