            aOrbiterD = ((aOrbiterD ^ aOrbiterA) ^ 0x3B5301BA9F08D1D7ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x1B3546485326D839ULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xC7111F91C4AF4A26ULL;
