            aWandererH = aWandererH ^ ((RotL64(aScatter, 41U) + aOrbiterE) + RotL64(aOrbiterK, 30U));
            aWandererI = aWandererI + (((RotL64(aCross, 20U) + RotL64(aOrbiterK, 23U)) + aOrbiterB) + RotL64(aCarry, 35U));
            aWandererF = aWandererF ^ (((RotL64(aPrevious, 57U) + RotL64(aOrbiterF, 51U)) + aOrbiterD) + aKeyRotateWandererUpdateSaltF[((aIndex + 20U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererF, 21U) ^ aWandererC);
