            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x7586C41292B360DAULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0x11DB2FED46CE9C90ULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 28U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x8AC05ED1D33BB5C7ULL), 3U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0xA8C4663380F8B9D8ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 9U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x8D3E6DBC465A42F0ULL;
