            aIngress ^= (RotL64(aAetherLaneA[((aIndex + 13238U)) & S_BLOCK1], 43U) ^ RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 12511U)) & S_BLOCK1], 23U));
