            aOrbiterH = ((aOrbiterH ^ aOrbiterA) ^ 0xFB0247C49E3CE2A9ULL) ^ aKeySpawnOrbiterUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1];
