            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x406A93765F0E105CULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xAA0FA66F4F644F3EULL;
            aOrbiterF = RotL64((aOrbiterF * 0xCB06E79B2DF4850FULL), 23U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0xE897169DBDE9CCB4ULL) + aKeySpawnOrbiterUpdateSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x07CF4CF18DFA4B81ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xBB16B566D7616909ULL), 19U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x281CD528A1B75C57ULL) + aKeySpawnOrbiterUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x9DBAFA8E3C68309FULL;
